do { Clear-Host; Write-Host "" ; Write-Host "╔════════════════════════════════════════╗" -ForegroundColor Cyan; Write-Host "║   SISTEMA BASE ESPERANZA - MARTE 2150   ║" -ForegroundColor Cyan; Write-Host "║        Gestión de Suministros           ║" -ForegroundColor Cyan; Write-Host "╚════════════════════════════════════════╝" -ForegroundColor Cyan; Write-Host ""; Write-Host "1. ➕ Registrar nuevo suministro" -ForegroundColor Green; Write-Host "2. 📋 Ver suministros registrados" -ForegroundColor Blue; Write-Host "3. 🚪 Salir del sistema" -ForegroundColor Red; Write-Host ""; $opcion = Read-Host "Ingrese su opción (1-3)"; switch ($opcion) { "1" { Write-Host "`n🔄 Cargando módulo de registro..." -ForegroundColor Yellow; Start-Sleep -Milliseconds 500; . "./Registro.ps1" } "2" { Write-Host "`n🔄 Cargando módulo de visualización..." -ForegroundColor Yellow; Start-Sleep -Milliseconds 500; . "./Visor.ps1" } "3" { Write-Host "`n🚀 Cerrando sesión. ¡Que vaya bien en Marte!" -ForegroundColor Cyan; exit } Default { Write-Host "`n❌ Opción no válida. Intente nuevamente." -ForegroundColor Red; pause } } } while ($opcion -ne "3")